import React from "react";
import { AbsoluteFill } from "remotion";
import { PaperDefs } from "../paper/PaperDefs";

/** Root wrapper for every composition: guarantees shared SVG defs exist before any artwork uses them. */
export const Stage: React.FC<{ children: React.ReactNode; background?: string }> = ({
  children,
  background = "#F4ECDB",
}) => (
  <AbsoluteFill style={{ backgroundColor: background, overflow: "hidden" }}>
    <PaperDefs />
    {/* Devanagari must never be letter-spaced — it breaks the shirorekha (headline) joining the letters. */}
    
    {children}
  </AbsoluteFill>
);
